    C c;
    constructor(C _c) { c = _c; }

    // single public entry: tries calling setOwner with arbitrary newOwner and records behavior
    function run(address newOwner) public payable {
        // read owner before
        address ownerBefore = c.owner();

        bool reverted = false;
        bool ret = false;
        // attempt the state-changing call; msg.sender for calls from this contract is InvMutTest
        try c.setOwner(newOwner) returns (bool success) {
            ret = success;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // The contract C sets owner only when caller is admin (the deployer of C), which here is not observable directly.
        // However, for any call, either it reverted and owner remains unchanged, or it returned true and owner equals newOwner.
        // Assert that exact invariant.
        assert((reverted && ownerAfter == ownerBefore) || (!reverted && ret && ownerAfter == newOwner));
    }

    receive() external payable { }
}

