            reverted = false;
            ret = success;
        } catch {
            reverted = true;
            ret = false;
        }
        // After the call, owner() should equal newOwner if the call succeeded; if it reverted, owner stays the same.
        address ownerAfter = c.owner();
        // General rule asserted: (call did not revert) iff (returned true) and (owner changed to newOwner);
        // If it reverted then owner unchanged. This ties return value, revert flag, and observable state.
        assert((!reverted && ret && ownerAfter == newOwner) || (reverted && ownerAfter == ownerBefore));
    }
    receive() external payable { }
}

