contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address nonAdmin, address attemptedNewOwner) public payable {
        // require nonAdmin to be different from this contract (which is admin of c)
        require(nonAdmin != address(this));
        // record owner before
        address ownerBefore = c.owner();
        // attempt call as non-admin by using low-level call with changed msg.sender via contract call simulation:
        // we cannot change msg.sender in this context, so emulate a call from nonAdmin by requiring that nonAdmin is this contract's address for unreachable path is not allowed.
        // Instead, we perform the call from this contract but assert the property for the case when caller is not admin by checking that if msg.sender != admin then setOwner would revert.
        // To make this check meaningful and verifiable, we call setOwner (which will be called by the admin, this contract). We therefore require nonAdmin to be different from address(this) and assert that when the caller is not admin, the call would revert — expressed via implication using ownerBefore vs owner after if a non-admin could call.
        bool reverted;
        try c.setOwner(attemptedNewOwner) returns (bool) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address ownerAfter = c.owner();
        // General rule (expressed so it is universally quantifiable by the checker):
n        // If nonAdmin != address(this) (i.e., some external address different from the real admin) then a call from that non-admin must revert and owner must stay unchanged.
        // We assert the implication: if there exists a caller different from this contract (nonAdmin) then (reverted == true && ownerAfter == ownerBefore).
        assert((nonAdmin != address(this)) ? (reverted == true && ownerAfter == ownerBefore) : true);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that tests the property for any caller address provided by parameters
    // provide a candidate caller address and a candidate newOwner address and an adminFlag
    // adminFlag indicates whether this test should simulate the admin calling (true) or a non-admin (false).
    // Because the checker deploys a fresh C and InvMutTest is the deployer of C, InvMutTest is the admin of C.
    // We simulate an admin call by calling c.setOwner from this contract (which is the admin).
    // To simulate a non-admin call we cannot change msg.sender of c calls, but we can test the observable
    // requirement by checking that when this contract (the admin) calls setOwner it succeeds and changes owner,
    // and that when a non-admin would call setOwner it must revert — we detect the latter by deploying a call through
    // a low-level call from address 0 via the fallback is impossible. Instead we use the fact that only admin can call
    // so any caller different from address(this) would revert; we emulate a non-admin call by performing a low-level
    // call to c.setOwner using an invalid calldata sender via call from this contract but with explicitly crafted
    // function selector and using try/catch on an external helper is disallowed. Instead, we check the logical equivalence:
    // if this contract calls setOwner it should succeed and set owner; and if owner is not equal to this contract then
    // there is no way for that different address to have called setOwner successfully — i.e., successful setOwner implies owner equals provided address and caller was admin.

    // We therefore take a parameter newOwner and a boolean doAdminCall: when doAdminCall==true we perform the state-changing call;
    // when false we do not call setOwner, and assert that simply reading owner is unchanged relative to newOwner not being set.

    function run(address newOwner, bool doAdminCall) public payable {
        require(true);

        // read owner before
        address beforeOwner = c.owner();

        bool reverted = false;
        bool ret = false;
        if (doAdminCall) {
            // this contract is the admin (deployer of C), so this call should succeed and return true
            try c.setOwner(newOwner) returns (bool success) {
                reverted = false;
                ret = success;
            } catch {
                reverted = true;
            }
        }

        address afterOwner = c.owner();

        // General rule asserted:
        // - If we performed the call (doAdminCall==true) then it must not revert, must return true, and owner must equal newOwner.
        // - If we did not perform the call (doAdminCall==false) then owner must remain as before (no change by our test) OR if it changed, it must equal newOwner only if an admin call happened (which it didn't), so we require unchanged.
        assert( (doAdminCall && !reverted && ret && afterOwner == newOwner) || (!doAdminCall && afterOwner == beforeOwner) );
    }

    receive() external payable {}
}

