        // observe owner before any mutation
        address ownerBefore = c.owner();

        // We'll perform the state-changing call as a top-level statement if requested.
        bool callPerformed = doCall;
        bool reverted;
        bool returnedBool;

        if (!doCall) {
            // no call: set flags accordingly
            reverted = false;
            returnedBool = false;
        } else {
            // Top-level try/catch call on c as required
            try c.setOwner(newOwner) returns (bool ok) {
                reverted = false;
                returnedBool = ok;
            } catch {
                reverted = true;
                returnedBool = false;
            }
        }

        address ownerAfter = c.owner();

        // General rule asserted for all inputs and behaviors:
        // - If we did not perform the call, owner is unchanged.
        // - If we performed the call and it reverted, owner is unchanged.
        // - If we performed the call and it did not revert, the call returned true and owner equals newOwner.
        assert((!callPerformed && ownerAfter == ownerBefore) ||
               (callPerformed && reverted && ownerAfter == ownerBefore) ||
               (callPerformed && !reverted && returnedBool == true && ownerAfter == newOwner));
    }

    receive() external payable {}
}

