contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: inputs are caller (simulated by trying call from this contract),
    // and a candidate newOwner address. We also take a boolean chooseAdmin to decide whether to
    // attempt the call as the original admin (which is the deployer of C, i.e., this contract)
    // or as an outsider. Because the checker runs the whole transaction as this contract,
    // we cannot change msg.sender. To simulate a non-admin caller, we rely on the fact that
    // only the original admin (the deployer of C) equals address(this) — so we instead check
    // the observable difference: calling setOwner will succeed (return true and change owner)
    // when this contract is admin; otherwise it must revert. We therefore expose chooseAdmin
    // to indicate whether we expect success (true) or revert (false).
    function run(address newOwner, bool expectSuccess) public payable {
        require(newOwner != address(0));

        // Read owner before the call via public getter
        address beforeOwner = c.owner();

        bool reverted;
        bool ret;
        // Make the state-changing call to c.setOwner; it must be a top-level statement.
        // We capture whether it reverts using try/catch and the return value if not reverted.
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            ret = success;
        } catch {
            reverted = true;
            ret = false;
        }

        address afterOwner = c.owner();

        // General rule asserted:
        // - If call reverted then owner must be unchanged and expectSuccess must be false.
        // - If call succeeded then it must have returned true, owner must equal newOwner, and expectSuccess must be true.
        assert((reverted && afterOwner == beforeOwner && !expectSuccess) ||
               (!reverted && ret && afterOwner == newOwner && expectSuccess));
    }

    receive() external payable {}
}
